package com.tripnest.entity; import jakarta.persistence.*; import java.time.LocalDateTime; @Entity @Table(name="contact_messages") public class ContactMessage { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; String name; String email; String subject; @Column(columnDefinition="TEXT") String message; @Column(name="created_at") LocalDateTime createdAt; @PrePersist void create(){createdAt=LocalDateTime.now();} public void setName(String v){name=v;} public void setEmail(String v){email=v;} public void setSubject(String v){subject=v;} public void setMessage(String v){message=v;} }
